from urllib.request import urlopen
from html.parser import HTMLParser

html=urlopen('https://landregistry.github.io/bgtechdoc/services/online_owner_verification/', timeout=20).read().decode('utf-8','replace')

class P(HTMLParser):
    def __init__(self):
        super().__init__(); self.in_main=False; self.stack=[]; self.buf=[]; self.out=[]; self.href=None
    def handle_starttag(self, tag, attrs):
        attrs=dict(attrs)
        if tag=='main': self.in_main=True
        if not self.in_main: return
        self.stack.append(tag)
        if tag in ['h1','h2','h3','h4','p','li','th','td','caption','a']:
            self.buf=[]
            if tag=='a': self.href=attrs.get('href')
        if tag=='tr': self.out.append('\nTR:')
        if tag=='table': self.out.append('\nTABLE_START')
    def handle_endtag(self, tag):
        if not self.in_main: return
        if tag in ['h1','h2','h3','h4','p','li','th','td','caption','a']:
            text=' '.join(''.join(self.buf).split())
            if text:
                prefix={'h1':'#','h2':'##','h3':'###','h4':'####','p':'P','li':'LI','th':'TH','td':'TD','caption':'CAP','a':'A'}[tag]
                if tag=='a' and self.href:
                    text=f'{text} -> {self.href}'
                self.out.append(f'{prefix}: {text}')
            self.buf=[]
            if tag=='a': self.href=None
        if tag=='table': self.out.append('TABLE_END\n')
        if tag=='main': self.in_main=False
        if self.stack: self.stack.pop()
    def handle_data(self, data):
        if self.in_main and self.stack and self.stack[-1] in ['h1','h2','h3','h4','p','li','th','td','caption','a']:
            self.buf.append(data)

p=P(); p.feed(html)
print('\n'.join(p.out))
