from urllib.request import urlopen
from html.parser import HTMLParser
from html import unescape

html=urlopen('https://landregistry.github.io/bgtechdoc/services/online_owner_verification/', timeout=20).read().decode('utf-8','replace')

class TableParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.tables=[]; self.in_table=False; self.in_row=False; self.in_cell=False
        self.current_table=[]; self.current_row=[]; self.current_cell=[]
    def handle_starttag(self, tag, attrs):
        if tag=='table':
            self.in_table=True; self.current_table=[]
        elif self.in_table and tag=='tr':
            self.in_row=True; self.current_row=[]
        elif self.in_table and tag in ('th','td'):
            self.in_cell=True; self.current_cell=[]
        elif self.in_cell and tag=='br':
            self.current_cell.append(' ')
    def handle_endtag(self, tag):
        if self.in_table and tag in ('th','td') and self.in_cell:
            text=' '.join(unescape(''.join(self.current_cell)).split())
            self.current_row.append(text)
            self.in_cell=False
        elif self.in_table and tag=='tr' and self.in_row:
            if self.current_row:
                self.current_table.append(self.current_row)
            self.in_row=False
        elif tag=='table' and self.in_table:
            self.tables.append(self.current_table)
            self.in_table=False
    def handle_data(self, data):
        if self.in_cell:
            self.current_cell.append(data)

p=TableParser(); p.feed(html)
for i,t in enumerate(p.tables,1):
    print(f'\nTABLE {i}')
    for row in t:
        print(' || '.join(row))
